"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[33383],{57085:e=>{e.exports=JSON.parse('{"label":"dapps","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/tags/dapps","allTagsPath":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/tags","count":16,"items":[{"id":"version-0.9/assets-handling","title":"Assets handling","description":"Assets exist on the base layer, which is where they have actual meaning and value. As with any execution layer solution, a Cartesi dApp that wants to manipulate assets (e.g. to allow players to bet on a game, so that the winner receives the loser\'s assets) needs a secure way of \\"teleporting\\" the assets from the base layer to the execution layer, and then a way to \\"teleport\\" them back to the base layer.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/assets-handling"},{"id":"version-0.9/migration-guides/from-08-to-09","title":"Breaking Changes v0.9","description":"This guide is designed to highlight the key distinctions between v0.8 and v0.9, offering assistance to those transitioning an existing application or individuals already acquainted with v0.8 who require a concise overview.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/migration-guides/from-08-to-09"},{"id":"version-0.9/build-dapps/create-dapp","title":"Create your first dApp","description":"Once you learned how to run a simple example, it is now time to create one of your own. In order to do this, we will make use of the existing dApps available in Cartesi\'s rollups-examples Github repository. Once again, make sure you have installed all the necessary requirements before proceeding.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/build-dapps/create-dapp"},{"id":"version-0.9/dapp-architecture","title":"dApp architecture","description":"Borrowing from familiar mainstream terminology, from a developer\u2019s point of view a Cartesi dApp is developed by implementing two main components: a front-end and a back-end.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/dapp-architecture"},{"id":"version-0.9/dapp-life-cycle","title":"dApp life cycle","description":"Now that we have described the architecture of a Cartesi dApp and how the front-end and back-end communicate with the Cartesi Rollups framework, let\u2019s step back a bit to discuss how a dApp can be implemented in practice.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/dapp-life-cycle"},{"id":"version-0.9/build-dapps/deploying-dapps","title":"Deploying dApps","description":"Please check the full documentation for deploying Rollups dApps to Cartesi\'s cloud-based execution infrastructure.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/build-dapps/deploying-dapps"},{"id":"version-0.9/build-dapps/requirements","title":"General requirements","description":"To start developing applications using Cartesi Rollups, first make sure that the packages listed in this section are all installed and working in your system. The instructions listed below should be enough to turn a fresh copy of the latest Ubuntu LTS distribution into a fully fledged Cartesi development environment.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/build-dapps/requirements"},{"id":"version-0.9/main-concepts","title":"Main concepts","description":"As explained in the previous section, the Cartesi Rollups framework achieves scalability by moving the bulk of the computation outside the blockchain, using the ledger as a data source but not as an execution environment. As such, the solution contains both on-chain (L1) and off-chain (L2) components.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/main-concepts"},{"id":"version-0.9/build-dapps/overview","title":"Overview","description":"Navigate to our Quick Start tutorial if you want to build dApps now!","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/build-dapps/overview"},{"id":"version-0.9/http-api","title":"Overview","description":"In a Cartesi dApp, the front-end and back-end parts of the application communicate with each other through the Rollups framework via a set of HTTP APIs.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/http-api"},{"id":"version-0.9/overview","title":"Overview","description":"The combination of an Optimistic Rollups framework and the Cartesi Machine Emulator enables the development of smart contracts and dApps using any package or library that is available for Linux. This allows developers to break free from the scalability limitations of the Ethereum Virtual Machine (EVM), and brings the rise of a new blockchain era to handle real-life and complex use cases.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/overview"},{"id":"version-0.9/build-dapps/guidelines","title":"Performance recommendations","description":"The Cartesi Rollups framework offers a plethora of possibilities for developing dApps, giving you the freedom to choose the technologies and stacks that align with your goals. Nonetheless, it is essential to consider certain recommendations to ensure that the dApps work seamlessly, given the current state of the Cartesi Rollups framework.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/build-dapps/guidelines"},{"id":"version-0.9/build-dapps/run-dapp","title":"Quick Start","description":"This article explains how to build and interact with a minimalistic Cartesi Rollups application.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/build-dapps/run-dapp"},{"id":"version-0.9/reading-outputs","title":"Reading outputs","description":"In Cartesi Rollups, the outputs include:","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/reading-outputs"},{"id":"version-0.9/build-dapps/dapp-host-mode","title":"Run back-end in Host Mode","description":"When developing an application, it is often important to easily test and debug it. For that matter, it is possible to run the Cartesi Rollups environment in host mode, so that the dApp\'s back-end can be executed directly on the host machine, allowing it to be debugged using regular development tools such as an IDE.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/build-dapps/dapp-host-mode"},{"id":"version-0.9/sending-requests","title":"Sending requests","description":"In Cartesi Rollups, there are two kinds of requests that can be made to the dApp:","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/sending-requests"}]}')}}]);